	defer ReturnPanicError(ch)
	codes := GetArg(optionalArgs, 0, nil)
	_ = codes
	params := GetArg(optionalArgs, 1, map[string]any{})
	_ = params
	if IsEqual(this.Markets, nil) {

		retRes323712 := (<-this.LoadMarkets())
		PanicOnError(retRes323712)
	}
